class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius             # routed through the setter below

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("below absolute zero")
        self._celsius = value

    @property
    def fahrenheit(self):                  # computed view, never stale
        return self._celsius * 9 / 5 + 32

t = Temperature(25)
assert t.fahrenheit == 77.0
t.celsius = 100                            # validation runs on EVERY write
assert t.fahrenheit == 212.0
try:
    t.celsius = -300
    ok = False
except ValueError:
    ok = True
assert ok, "setter rejected the invalid write"

# __init__ goes through the same gate — no back door at construction time
try:
    Temperature(-400)
    ok = False
except ValueError:
    ok = True
assert ok

