# The diamond: which who() wins?
class A:
    def who(self): return "A"
class B(A):
    def who(self): return "B"
class C(A):
    def who(self): return "C"
class D(B, C):
    pass

assert [k.__name__ for k in D.mro()] == ["D", "B", "C", "A", "object"]
assert D().who() == "B"          # leftmost base wins for a plain lookup

# Cooperative super(): one call threads through the WHOLE MRO
class Base:
    def greet(self):
        return ["Base"]
class Left(Base):
    def greet(self):
        return ["Left"] + super().greet()
class Right(Base):
    def greet(self):
        return ["Right"] + super().greet()
class Child(Left, Right):
    def greet(self):
        return ["Child"] + super().greet()

# Inside Left, super() is RIGHT here — not Base — because the object is a Child
assert Child().greet() == ["Child", "Left", "Right", "Base"]
assert Left().greet() == ["Left", "Base"]   # same code, different MRO, different route

# An impossible order is rejected at class-creation time
class P: pass
class Q: pass
class X(P, Q): pass
class Y(Q, P): pass
try:
    class Z(X, Y): pass          # C3 cannot satisfy both orders
    ok = False
except TypeError:
    ok = True
assert ok, "inconsistent MRO must raise TypeError"
print("MRO OK:", [k.__name__ for k in Child.mro()])

# Road 1: duck typing — no shared base class, only a shared method name
class JsonDoc:
    def render(self): return '{"ok": true}'
class XmlDoc:
    def render(self): return "<ok/>"

def publish(doc):
    return doc.render()          # works for ANY object with .render()

assert publish(JsonDoc()) == '{"ok": true}'
assert publish(XmlDoc()) == "<ok/>"

class NoRender:
    pass
try:
    publish(NoRender())          # failure happens LATE, at call time
    ok = False
except AttributeError:
    ok = True
assert ok

# Road 2: abc — the contract is enforced at instantiation time
from abc import ABC, abstractmethod

class Notifier(ABC):
    @abstractmethod
    def send(self, msg): ...

class Email(Notifier):
    def send(self, msg): return f"email: {msg}"
class Sms(Notifier):
    def send(self, msg): return f"sms: {msg}"

# one loop, many behaviors — the definition of polymorphism
outs = [n.send("hi") for n in (Email(), Sms())]
assert outs == ["email: hi", "sms: hi"]

try:
    Notifier()                   # abstract classes cannot be instantiated
    ok = False
except TypeError:
    ok = True
assert ok

class Push(Notifier):            # forgot to implement send()
    pass
try:
    Push()                       # fails EARLY, before any message is lost
    ok = False
except TypeError:
    ok = True
assert ok
assert isinstance(Email(), Notifier) and issubclass(Sms, Notifier)
print("polymorphism OK")

from abc import ABC, abstractmethod

class PaymentProcessor(ABC):
    """The abstraction: WHAT every processor does, not HOW."""

    @abstractmethod
    def charge(self, amount): ...

    def pay(self, amount):                 # template method: shared skeleton
        if amount <= 0:
            raise ValueError("amount must be positive")
        return self.charge(amount)         # the one variable step

class StripeProcessor(PaymentProcessor):
    def charge(self, amount): return f"stripe:{amount}"

class RazorpayProcessor(PaymentProcessor):
    def charge(self, amount): return f"razorpay:{amount}"

# Callers depend on the verb, not the vendor
def checkout(processor: PaymentProcessor, amount):
    return processor.pay(amount)

assert checkout(StripeProcessor(), 100) == "stripe:100"
assert checkout(RazorpayProcessor(), 50) == "razorpay:50"

# The skeleton's validation is shared — written once, holds for every vendor
try:
    checkout(StripeProcessor(), -5)
    ok = False
except ValueError:
    ok = True
assert ok

try:
    PaymentProcessor()                     # abstractions cannot be instantiated
    ok = False
except TypeError:
    ok = True
assert ok

class Broken(PaymentProcessor):            # forgot to implement charge()
    pass
try:
    Broken()
    ok = False
except TypeError:
    ok = True
assert ok
print("abstraction OK")

# INHERITANCE version: Stack IS-A list — and leaks the whole list API
class BadStack(list):
    def push(self, x): self.append(x)
    def pop_top(self): return self.pop()

s = BadStack()
s.push(1); s.push(2)
s.insert(0, 99)                  # a caller can violate LIFO — API leaked
assert s[0] == 99                # not a stack anymore, no error raised
assert len([m for m in dir(s) if not m.startswith("_")]) > 10  # bloated API

# COMPOSITION version: Stack HAS-A list, exposes only what a stack is
class Stack:
    def __init__(self):
        self._items = []         # the list is an implementation detail

    def push(self, x):
        self._items.append(x)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def __len__(self):           # forwarding: small, explicit, chosen
        return len(self._items)

st = Stack()
st.push(1); st.push(2)
assert st.pop() == 2 and st.pop() == 1     # LIFO holds
assert not hasattr(st, "insert")           # nothing leaked
try:
    st.pop()
    ok = False
except IndexError:
    ok = True
assert ok

# Swap the inner structure — zero caller changes needed
from collections import deque
class DequeStack(Stack):
    def __init__(self):
        self._items = deque()    # different engine, same public API

d = DequeStack()
d.push("a"); d.push("b")
assert d.pop() == "b" and len(d) == 1
print("composition OK: tight API, swappable internals")

from abc import ABC, abstractmethod

# --- I: small role interfaces, no forced fake methods ---
class Printer(ABC):
    @abstractmethod
    def print_doc(self, doc): ...

class Scanner(ABC):
    @abstractmethod
    def scan(self): ...

class OldPrinter(Printer):               # implements ONLY what it can do
    def print_doc(self, doc): return f"printed {doc}"

class MultiFunction(Printer, Scanner):   # opts into BOTH roles honestly
    def print_doc(self, doc): return f"printed {doc}"
    def scan(self): return "scan.png"

assert OldPrinter().print_doc("cv") == "printed cv"
assert not isinstance(OldPrinter(), Scanner)     # it never claims to scan
mf = MultiFunction()
assert isinstance(mf, Printer) and isinstance(mf, Scanner)
assert mf.scan() == "scan.png"

# --- D: depend on the abstraction, inject the concrete at the edge ---
class Store(ABC):
    @abstractmethod
    def save(self, key, value): ...
    @abstractmethod
    def load(self, key): ...

class MemoryStore(Store):                # the test double IS a real Store
    def __init__(self): self._d = {}
    def save(self, key, value): self._d[key] = value
    def load(self, key): return self._d[key]

class UserService:                       # high-level policy, zero driver imports
    def __init__(self, store: Store):    # injected, not constructed inside
        self.store = store
    def register(self, name):
        if not name:
            raise ValueError("name required")
        self.store.save(name, {"name": name})
        return self.store.load(name)

svc = UserService(MemoryStore())         # composition root wires it up
assert svc.register("asha") == {"name": "asha"}
try:
    svc.register("")
    ok = False
except ValueError:
    ok = True
assert ok
print("SOLID I/D OK — service tested with no database in sight")

class Money:
    __slots__ = ("amount", "currency")     # fixed attributes, less memory

    def __init__(self, amount, currency="INR"):
        self.amount = amount
        self.currency = currency

    def __repr__(self):                    # unambiguous, rebuildable
        return f"Money({self.amount}, {self.currency!r})"

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented          # refuse politely, never raise
        return (self.amount, self.currency) == (other.amount, other.currency)

    def __hash__(self):                    # __eq__ without this = unhashable
        return hash((self.amount, self.currency))

    def __add__(self, other):
        if not isinstance(other, Money) or other.currency != self.currency:
            return NotImplemented
        return Money(self.amount + other.amount, self.currency)

    def __lt__(self, other):               # unlocks sorted(), min(), max()
        return self.amount < other.amount

assert Money(5) + Money(7) == Money(12)
assert repr(Money(5)) == "Money(5, 'INR')"
assert sorted([Money(9), Money(1)])[0] == Money(1)
assert len({Money(5), Money(5)}) == 1      # eq + hash make it set-safe

try:
    Money(1) + 1                           # both sides refuse -> TypeError
    ok = False
except TypeError:
    ok = True
assert ok

m = Money(1)
try:
    m.amout = 5                            # typo — __slots__ catches it
    ok = False
except AttributeError:
    ok = True
assert ok

class Basket:                              # container protocol
    def __init__(self): self._items = []
    def add(self, item): self._items.append(item)
    def __len__(self): return len(self._items)
    def __iter__(self): return iter(self._items)
    def __contains__(self, item): return item in self._items

b = Basket()
assert not b                               # __len__ == 0 -> falsy
b.add(Money(5))
assert len(b) == 1 and Money(5) in b and list(b) == [Money(5)]
print("dunder protocol OK")

# Singleton via __new__: one cached instance, always returned
class Config:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance.values = {}      # init once, not per call
        return cls._instance

a, b = Config(), Config()
a.values["env"] = "prod"
assert a is b                              # the SAME object
assert b.values["env"] == "prod"

# Why it is disliked — test pollution, demonstrated:
def test_one():
    Config().values["flag"] = True         # "independent" test mutates global

def test_two():
    return Config().values.get("flag")     # never set it, still sees it

test_one()
assert test_two() is True                  # order-dependent tests = flaky suite

# Factory: ONE place decides which concrete class to build
import json

class JsonParser:
    def parse(self, text): return json.loads(text)

class CsvParser:
    def parse(self, text): return [row.split(",") for row in text.splitlines()]

PARSERS = {"json": JsonParser, "csv": CsvParser}   # the registry

def parser_for(filename):
    ext = filename.rsplit(".", 1)[-1].lower()
    if ext not in PARSERS:
        raise ValueError(f"no parser for .{ext}")
    return PARSERS[ext]()

assert parser_for("data.json").parse('{"a": 1}') == {"a": 1}
assert parser_for("data.csv").parse("a,b\nc,d") == [["a", "b"], ["c", "d"]]
try:
    parser_for("data.xml")                 # unknown format fails fast + clear
    ok = False
except ValueError:
    ok = True
assert ok

PARSERS["tsv"] = type("TsvParser", (), {   # extension: one registry entry
    "parse": lambda self, text: [r.split("\t") for r in text.splitlines()]})
assert parser_for("x.tsv").parse("a\tb") == [["a", "b"]]
print("singleton + factory OK")

# STRATEGY: the algorithm is injected; the context never changes
class Checkout:
    def __init__(self, pricing):           # pricing: any callable price->price
        self.pricing = pricing
    def total(self, base):
        return self.pricing(base)

regular = Checkout(lambda p: p)
diwali = Checkout(lambda p: p * 0.8)       # new promo = new function only
member = Checkout(lambda p: max(p - 50, 0))
assert regular.total(100) == 100
assert diwali.total(100) == 80
assert member.total(30) == 0

# OBSERVER: publisher fires events; it never imports its subscribers
class EventBus:
    def __init__(self): self._subs = {}
    def subscribe(self, event, fn):
        self._subs.setdefault(event, []).append(fn)
    def publish(self, event, payload):
        for fn in self._subs.get(event, []):
            fn(payload)

log, emails = [], []
bus = EventBus()
bus.subscribe("order_placed", lambda o: log.append(f"log {o}"))
bus.subscribe("order_placed", lambda o: emails.append(f"mail {o}"))
bus.publish("order_placed", 42)
bus.publish("unknown_event", 1)            # zero subscribers: safely ignored
assert log == ["log 42"] and emails == ["mail 42"]

# DECORATOR (pattern): wrap an object, same interface, stackable add-ons
class Coffee:
    def cost(self): return 40
class WithMilk:
    def __init__(self, inner): self.inner = inner
    def cost(self): return self.inner.cost() + 10
class WithSugar:
    def __init__(self, inner): self.inner = inner
    def cost(self): return self.inner.cost() + 5

assert WithSugar(WithMilk(Coffee())).cost() == 55
assert WithMilk(WithMilk(Coffee())).cost() == 60   # any combo, no new classes

# Python's @ syntax: the same pattern applied to functions
calls = []
def audited(fn):
    def wrapper(*args, **kwargs):
        calls.append(fn.__name__)
        return fn(*args, **kwargs)
    return wrapper

@audited
def pay(amount): return f"paid {amount}"

assert pay(10) == "paid 10" and calls == ["pay"]
print("strategy + observer + decorator OK")

# Trap 1: mutable default — evaluated ONCE, at def time
def buggy_append(item, bucket=[]):
    bucket.append(item)
    return bucket

assert buggy_append(1) == [1]
assert buggy_append(2) == [1, 2]           # surprise: same list survived
assert buggy_append.__defaults__ == ([1, 2],)  # it lives ON the function

def fixed_append(item, bucket=None):
    if bucket is None:
        bucket = []                        # fresh list per call
    bucket.append(item)
    return bucket

assert fixed_append(1) == [1]
assert fixed_append(2) == [2]              # independent calls, as expected

# Trap 2: class attr — mutation SHARES, assignment SHADOWS
class Team:
    members = []                           # ONE list on the class

t1, t2 = Team(), Team()
t1.members.append("asha")                  # mutation reaches the shared list
assert t2.members == ["asha"]              # t2 sees t1's change

class FixedTeam:
    def __init__(self):
        self.members = []                  # one list PER object

f1, f2 = FixedTeam(), FixedTeam()
f1.members.append("asha")
assert f2.members == []

class Counter:
    count = 0
c = Counter()
c.count += 1                               # reads class 0, writes INSTANCE 1
assert c.count == 1
assert Counter.count == 0                  # the class was never touched
assert "count" in c.__dict__               # the shadow, visible

# Trap 3: super() follows the object's MRO, not the textual parent
class A:
    def setup(self): return ["A"]
class B(A):
    def setup(self): return ["B"] + super().setup()
class C(A):
    def setup(self): return ["C"] + super().setup()
class D(B, C):
    def setup(self): return ["D"] + super().setup()

# Inside B, super() routes to C here — a class B never mentions
assert D().setup() == ["D", "B", "C", "A"]
assert B().setup() == ["B", "A"]           # same line of code, different route
print("all three traps demonstrated")
